-- MySQL dump 10.13  Distrib 8.0.46, for Linux (x86_64) -- -- Host: localhost    Database: kidrive -- ------------------------------------------------------ -- Server version	8.0.46  /*!40101 SET @OLD_CHARACTER_SET_CLIENT=@@CHARACTER_SET_CLIENT */; /*!40101 SET @OLD_CHARACTER_SET_RESULTS=@@CHARACTER_SET_RESULTS */; /*!40101 SET @OLD_COLLATION_CONNECTION=@@COLLATION_CONNECTION */; /*!50503 SET NAMES utf8mb4 */; /*!40103 SET @OLD_TIME_ZONE=@@TIME_ZONE */; /*!40103 SET TIME_ZONE='+00:00' */; /*!40014 SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0 */; /*!40014 SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0 */; /*!40101 SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO' */; /*!40111 SET @OLD_SQL_NOTES=@@SQL_NOTES, SQL_NOTES=0 */;  -- -- Table structure for table `ai_chat_history` --  DROP TABLE IF EXISTS `ai_chat_history`; /*!40101 SET @saved_cs_client     = @@character_set_client */; /*!50503 SET character_set_client = utf8mb4 */; CREATE TABLE `ai_chat_history` (   `id_message` int NOT NULL AUTO_INCREMENT,   `id_user` int NOT NULL,   `id_sender` int NOT NULL,   `message_text` text NOT NULL,   `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,   PRIMARY KEY (`id_message`),   KEY `fk_chat_user_idx` (`id_user`),   KEY `fk_chat_sender` (`id_sender`),   CONSTRAINT `fk_chat_sender` FOREIGN KEY (`id_sender`) REFERENCES `chat_senders` (`id_sender`),   CONSTRAINT `fk_chat_user` FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`) ON DELETE CASCADE ON UPDATE CASCADE ) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci; /*!40101 SET character_set_client = @saved_cs_client */;  -- -- Dumping data for table `ai_chat_history` --  LOCK TABLES `ai_chat_history` WRITE; /*!40000 ALTER TABLE `ai_chat_history` DISABLE KEYS */; INSERT INTO `ai_chat_history` VALUES (21,1,1,'Привет, хочу подобрать себе машину на бензине. Чтобы марка была Мерседес','2026-10-07 00:20:46'),(22,1,2,'Здравствуйте! Я умный ассистент автосалона KIDRIVE. Я помогу подобрать идеальный автомобиль для тест-драйва! Напишите мне свои пожелания — например: «Нужен мощный седан до 4000 руб/час», «Ищу Mercedes на автомате» или «Покажи авто на бензине».','2026-10-07 00:20:46'),(23,2,1,'Привет, хочу подобрать себе машину БМВ, какие варианты предложишь?','2026-10-07 00:26:41'),(24,2,2,'По вашему запросу я подобрал отличные автомобили для тест-драйва:\n\n1. M5 F90 (2018 г.) — 4 500 ₽/час, мощность 600 л.с., топливо: Электро, КПП: АКПП.\n2. M5 E34 (1992 г.) — 3 500 ₽/час, мощность 192 л.с., топливо: Электро, КПП: МКПП.\n\nКакой из них хотите опробовать в деле? Выберите дату и время для бронирования!','2026-10-07 00:26:41'); /*!40000 ALTER TABLE `ai_chat_history` ENABLE KEYS */; UNLOCK TABLES;  -- -- Table structure for table `booking_statuses` --  DROP TABLE IF EXISTS `booking_statuses`; /*!40101 SET @saved_cs_client     = @@character_set_client */; /*!50503 SET character_set_client = utf8mb4 */; CREATE TABLE `booking_statuses` (   `id_status` int NOT NULL AUTO_INCREMENT,   `status_name` varchar(45) NOT NULL,   PRIMARY KEY (`id_status`) ) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci; /*!40101 SET character_set_client = @saved_cs_client */;  -- -- Dumping data for table `booking_statuses` --  LOCK TABLES `booking_statuses` WRITE; /*!40000 ALTER TABLE `booking_statuses` DISABLE KEYS */; INSERT INTO `booking_statuses` VALUES (1,'В рассмотрении'),(2,'Подтверждено'),(3,'Отменено'),(4,'Завершено'); /*!40000 ALTER TABLE `booking_statuses` ENABLE KEYS */; UNLOCK TABLES;  -- -- Table structure for table `bookings` --  DROP TABLE IF EXISTS `bookings`; /*!40101 SET @saved_cs_client     = @@character_set_client */; /*!50503 SET character_set_client = utf8mb4 */; CREATE TABLE `bookings` (   `id_booking` int NOT NULL AUTO_INCREMENT,   `id_user` int NOT NULL,   `id_car` int NOT NULL,   `booking_date` date NOT NULL,   `booking_time` time NOT NULL,   `id_status` int NOT NULL,   `id_payment` int NOT NULL,   PRIMARY KEY (`id_booking`),   KEY `user_idx` (`id_user`),   KEY `car_idx` (`id_car`),   KEY `status_idx` (`id_status`),   KEY `payment_idx` (`id_payment`),   CONSTRAINT `car` FOREIGN KEY (`id_car`) REFERENCES `cars` (`id_car`),   CONSTRAINT `pay` FOREIGN KEY (`id_payment`) REFERENCES `payment_methods` (`id_payment_method`),   CONSTRAINT `status` FOREIGN KEY (`id_status`) REFERENCES `booking_statuses` (`id_status`),   CONSTRAINT `user` FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`) ) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci; /*!40101 SET character_set_client = @saved_cs_client */;  -- -- Dumping data for table `bookings` --  LOCK TABLES `bookings` WRITE; /*!40000 ALTER TABLE `bookings` DISABLE KEYS */; INSERT INTO `bookings` VALUES (1,2,1,'2026-05-21','13:00:00',2,1),(2,2,1,'2026-05-21','09:00:00',2,1),(3,3,2,'2026-05-20','17:00:00',2,1),(4,3,4,'2026-05-20','10:00:00',3,1),(5,2,4,'2026-05-23','17:00:00',2,1),(6,4,4,'2026-05-24','16:00:00',2,2),(7,2,3,'2026-05-23','10:00:00',2,1),(8,6,12,'2026-06-02','16:00:00',3,2),(9,6,1,'2026-05-19','17:00:00',2,1),(10,2,19,'2026-05-19','09:00:00',3,1),(11,7,1,'2026-05-25','13:00:00',2,1),(12,7,1,'2026-05-25','09:00:00',2,1),(13,2,1,'2026-05-28','13:00:00',3,1),(14,2,1,'2026-05-28','14:00:00',2,1),(15,2,18,'2026-05-31','11:00:00',2,1),(16,2,17,'2026-05-29','09:00:00',3,1),(17,7,21,'2026-05-29','09:00:00',2,1),(18,2,1,'2026-05-30','09:00:00',2,1),(19,7,15,'2026-06-14','09:00:00',3,1),(20,7,13,'2026-06-14','09:00:00',2,1),(21,2,10,'2026-06-14','09:00:00',3,1),(22,2,3,'2026-06-20','10:00:00',2,2),(23,2,11,'2026-06-18','09:00:00',2,1),(24,7,1,'2026-06-20','15:00:00',3,1),(25,7,1,'2026-06-21','09:00:00',2,1),(26,7,2,'2026-06-22','12:00:00',3,1),(27,2,4,'2026-06-30','17:00:00',2,1); /*!40000 ALTER TABLE `bookings` ENABLE KEYS */; UNLOCK TABLES;  -- -- Table structure for table `cars` --  DROP TABLE IF EXISTS `cars`; /*!40101 SET @saved_cs_client     = @@character_set_client */; /*!50503 SET character_set_client = utf8mb4 */; CREATE TABLE `cars` (   `id_car` int NOT NULL AUTO_INCREMENT,   `id_category` int NOT NULL,   `model` varchar(45) NOT NULL,   `year_car` year NOT NULL,   `description` text NOT NULL,   `image_path` varchar(255) NOT NULL,   `is_deleted` tinyint NOT NULL,   `price` decimal(10,2) NOT NULL DEFAULT '0.00',   `power_hp` int DEFAULT NULL COMMENT 'Мощность в л.с.',   `id_fuel_type` int DEFAULT NULL,   `id_treansmission` int DEFAULT NULL,   PRIMARY KEY (`id_car`),   KEY `cat_idx` (`id_category`),   KEY `fuels_types_idx` (`id_fuel_type`),   KEY `transmissions_idx` (`id_treansmission`),   CONSTRAINT `cat` FOREIGN KEY (`id_category`) REFERENCES `categories` (`id_category`),   CONSTRAINT `fuels_types` FOREIGN KEY (`id_fuel_type`) REFERENCES `fuels_types` (`id`),   CONSTRAINT `transmissions` FOREIGN KEY (`id_treansmission`) REFERENCES `transmissions` (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci; /*!40101 SET character_set_client = @saved_cs_client */;  -- -- Dumping data for table `cars` --  LOCK TABLES `cars` WRITE; /*!40000 ALTER TABLE `cars` DISABLE KEYS */; INSERT INTO `cars` VALUES (1,3,'AMG CLE 53',2024,'3.0 рядная «шестёрка» M256M с электротурбиной (449 л.с., 560 Нм + 200 Нм от 48V стартер-генератора), полный привод 4MATIC+, 9-ступенчатый AMG Speedshift TCT. Разгон 0-100 за 4.2 с. Задние подруливающие колёса (до 2.5°), дрифт-режим (Drift Mode), пневмоподвеска с автоматическим уровнем кузова. Салон: кресла AMG Performance в кожзаме с микроволокном, руль с тремя спицами и круглым контроллером режимов, салонная подсветка 64 цветами, медиасистема MBUX с 11.9\" планшетом.','mercedes53.jpg',0,5500.00,435,2,1),(2,3,'E63 W212',2015,'Mercedes-Benz E63 W212 — это легендарный спортивный седан (и универсал), выпускавшийся с 2009 по 2016 год. Он сочетает комфорт бизнес-класса с суперкаровской динамикой. Автомобиль оснащался двумя мощнейшими V8 двигателями и предлагался как в заднеприводной (ранние версии), так и в полноприводной модификациях','mercedes212.jpg',0,10000.00,306,1,1),(3,1,'Camry',2021,'2.5 A25A-FKS (181 л.с., 231 Нм) или 3.5 V6 2GR-FKS (249 л.с., 356 Нм), передний привод, вариатор Direct Shift CVT с первой гидро-передачей (имитирует старт с автомата). Разгон: 9.1 с (2.5) или 7.5 с (3.5). Система Toyota Safety Sense 2.0: автоторможение, распознавание пешеходов и велосипедистов, ночной автосвет, адаптивный круиз. Салон: кожа, электрорегулировка водителя с памятью, 9\" медиасистема с JBL (опция), трёхзонный климат-контроль, подогрев всех кресел и руля.','toyotaCamry.jpg',0,1400.00,249,2,1),(4,1,'Supra',2025,'Toyota Supra — это легендарный японский спортивный автомобиль класса Gran Turismo, выпускающийся с 1978 года. Модель прославилась благодаря идеальной развесовке, заднему приводу и выдающимся характеристикам, став культовой классикой в мире дрифта, автоспорта и тюнинга','toyotaSupra.jpg',0,25000.00,340,1,1),(5,2,'M5 F90',2018,'4.4 V8 twin-turbo (600 л.с., 750 Нм), M xDrive с заднеприводным режимом (2WD), 8-ступенчатый M Steptronic. Разгон 0-100 за 3.4 с. Адаптивная подвеска M с электронноуправляемыми амортизаторами, активный M-дифференциал. Карбоновая крыша для снижения центра тяжести, лазерные фары BMW Laserlight, спортивная выхлопная система с регулируемыми заслонками. ','bmwM5.jpg',0,4500.00,600,2,1),(6,2,'M5 E34',1992,'3.8 рядная «шестёрка» (340 л.с., 400 Нм), задний привод, 5-ступенчатая механика Getrag. Разгон 0-100 за 5.9 с (для своего времени — феномен). Подвеска: McPherson спереди, многорычажка сзади, заниженный спортивный клиренс. Салон: кожа Nappa, передние кресла с электрорегулировкой и подогревом, бортовой компьютер с 13 кнопками. Культовый «броневик» с узнаваемыми порогами и обвесом.','bmwE34.jpg',0,3500.00,192,2,3),(7,8,'Q3',2018,'2.0 TFSI (180 л.с., 320 Нм), полный привод Quattro, 7-ступенчатый робот S tronic. Разгон 0-100 за 7.8 с. Подвеска независимая (McPherson спереди, многорычажка сзади). Салон: виртуальная приборка Audi Virtual Cockpit 12.3\", медиасистема MMI с 8.8\" экраном, отделка кожей и алькантарой. Опции: адаптивный круиз-контроль, система помощи при парковке с камерами 360°, подогрев всех сидений, двухзонный климат-контроль. Багажник 530 л.','audiQ3.jpg',0,1500.00,180,1,5),(8,8,'RS7',2020,'4.0 V8 twin-turbo (600 л.с., 800 Нм), 48V мягкий гибрид, полный привод Quattro с самоблокирующимся дифференциалом, 8-ступенчатый Tiptronic. Разгон 0-100 за 3.6 с. Пневмоподвеска с адаптивными амортизаторами, задний подруливающий мост, карбон-керамические тормоза (опция). Салон: спортивные кресла RS с ромбовидной прострочкой, трёхэкранная медиасистема (12.3\" + два 10.1\"), отделка карбоном и алькантарой. Оптика Matrix LED с лазерными фарами дальнего света.','audiRS7.jpg',0,5000.00,600,1,1),(9,4,'Civic',2022,'1.5 турбо VTEC (182 л.с., 240 Нм), передний привод, вариатор с имитацией 7 ступеней (или 6-ступ. механика на версии Sport). Разгон 0-100 за 8.0 с. Подвеска: McPherson спереди, многорычажка сзади. Система Honda Sensing: автоторможение, адаптивный круиз с функцией Stop&Go, удержание в полосе, распознавание знаков. Салон: цифровая приборка 10.2\", медиасистема с 9\" экраном, Apple CarPlay/Android Auto беспроводные, отделка тканью с контрастной прострочкой. Расход топлива 6.8 л/100 км.','hondaCivic.jpg',0,1200.00,140,1,3),(10,4,'S2000',2004,'2.2 F22C (240 л.с., 220 Нм при 6800 об/мин), задний привод, 6-ступенчатая короткоходная механика. Красная зона — 9000 об/мин, VTEC открывается после 6000 об/мин. Разгон 0-100 за 6.2 с. Подвеска: двойные поперечные рычаги (перед и зад) — идеальная управляемость, алюминиевые кулаки. Электрический жёсткий верх (хардтоп) или тканевый в базе. Салон: алюминиевые педали, кресла с высокой поддержкой, трёхспицевый руль MOMO, цифровая панель с барграфом оборотов. Классика JDM без экранов.','hondaS2000.jpg',0,3000.00,240,1,3),(11,7,'K5',2020,'2.5 GDI (194 л.с., 245 Нм), передний привод, 8-ступенчатый автомат. Разгон 0-100 за 8.9 с. Подвеска: McPherson спереди, многорычажка сзади. Две 12.3-дюймовые панели: цифровая приборка и медиасистема. Подогрев лобового стекла (нити в стекле), система предотвращения столкновений в слепых зонах с выводом картинки на приборку, адаптивный круиз. Фирменные ДХО «звёздное небо» (Star Map Lighting). Салон: кожа Nappa с перфорацией, вентиляция передних сидений, подогрев задних.','kiaK5.jpg',0,1300.00,194,1,1),(12,6,'Priora',2013,'1.6 (98 л.с., 145 Нм), передний привод, 5-ступ. механика или 4-ступ. автомат Jatco. Разгон 0-100 за 11.5 с (механика). Гидроусилитель руля (у поздних версий — ЭУР). Кондиционер (не климат), подогрев передних сидений, электростеклоподъёмники всех дверей. Аудиосистема с USB и AUX. Бюджетный ремонт и обслуживание, запчасти с разборки копейки. Салон: тканевая обивка, пластик серого цвета без особых излишеств, но всё нужное есть.','ladaPriora.jpg',0,1000.00,98,2,3),(13,5,'Passat',2019,'2.0 TSI EA888 Gen3 (190 л.с., 320 Нм), передний привод, 7-ступ. DSG DQ381 (с мокрыми сцеплениями). Разгон 0-100 за 7.5 с. Матричные фары IQ.Light с 48 LED на сторону, проекционный экран на лобовое стекло, массаж передних сидений ErgoComfort с пневмоподушками. Салон: «виртуальная приборка» Active Info Display 10.25\", медиасистема с 9.2\" экраном, голосовое управление, ассистент парковки с маневрированием из выезда.','volkswagenPassat.jpg',0,1300.00,180,1,5),(14,5,'Polo',2020,'1.4 TSI (125 л.с., 200 Нм), передний привод, 7-ступ. DSG (DQ200 с сухими сцеплениями). Разгон 0-100 за 9.2 с. Подвеска: McPherson спереди, полузависимая балка сзади. Датчики дождя и света, ESP с функцией стабилизации прицепа, 6 подушек безопасности (передние, боковые, шторки). Салон: цифровая приборка Digital Cockpit (опция), 6.5\" мультимедиа, отделка глянцевым чёрным пластиком. Пространства сзади больше, чем у многих одноклассников — 5 человек не теснятся.','bmwM3.jpg',0,1000.00,431,1,5),(15,9,'LX570',2016,'5.7 V8 3UR-FE (367 л.с., 530 Нм), полный привод с понижающей передачей и блокировкой дифференциала, 8-ступенчатый автомат Aisin. Разгон 0-100 за 7.7 с (для 2.7 тонн). Рама лестничного типа, пневмоподвеска с регулировкой дорожного просвета (от 210 до 320 мм), система активной стабилизации против кренов. Салон: кожа полуанилин, вставки из настоящего дерева, четырёхзонный климат-контроль, подогрев/вентиляция всех сидений, массаж передних крёсел, аудиосистема Mark Levinson с 19 динамиками. ','lexus570.jpg',0,4500.00,383,1,1),(16,9,'LC500',2018,'5.0 V8 2UR-GSE (477 л.с., 540 Нм), задний привод с активным дифференциалом, 10-ступенчатый автомат Direct Shift с гидротрансформатором. Разгон 0-100 за 4.4 с. Подвеска многорычажная с алюминиевыми рычагами, адаптивные амортизаторы Lexus Dynamic Handling System. Карбоновые двери (опция), задний спойлер выезжает на скорости 80 км/ч. Салон: кресла из кожи L-Aniline с 12-позиционной регулировкой, тачпад на центральной консоли, проекционный дисплей, аудиосистема Mark Levinson Reference с 12 динамиками.','lexus500.jpg',0,6000.00,477,1,1),(17,10,'Model 3',2021,'Электромотор на задней оси (RWD) — 283 л.с. или Dual Motor AWD — 450 л.с. Разгон 0-100: 5.9 с (RWD) или 4.2 с (AWD). Батарея 60 кВт·ч (RWD) или 75 кВт·ч (Long Range). Запас хода 491-629 км по WLTP. Подвеска: двухрычажка спереди, многорычажка сзади. Одна 15.4\" центральная панель вместо приборки, автопилот базовый (адаптивный круиз + удержание в полосе), стеклянная крыша. ','teslaModel.jpg',0,2500.00,283,2,4),(18,10,'Roadster ',2023,'Три электромотора (один спереди, два сзади) — около 1000 л.с. на базовой версии, до 2000 л.с. на пакете Space X (с опциональными реактивными соплами для ускорения). Разгон 0-100 за 1.9 секунды (база) или 1.1 секунды с пакетом Space X. Максималка 400+ км/ч. Запас хода около 1000 км на батарее 200 кВт·ч. Карбоновый монокок, съёмная жёсткая крыша. Салон: 4 места, руль-штурвал (у ранних прототипов), 17\" экран как у Model S, отделка алькантара. ','teslaRoadster.jpg',0,15000.00,288,2,4),(19,11,'Arrizo 6 Pro',2024,'1.6 TGDI (150 л.с., 275 Нм) или 1.5 Turbo (147 л.с.), передний привод, вариатор CVT25 (с имитацией 9 ступеней). Разгон 0-100 за 9.2 с. Подвеска: McPherson спереди, многорычажка сзади. Две 12.3-дюймовые панели (приборка + медиа), система Sonos 8 динамиков, 6 подушек безопасности, адаптивный круиз с остановкой и стартом. Салон: экокожа с перфорацией, вентиляция передних сидений, подогрев всех кресел, отделка мягким пластиком с прострочкой. Китайский рынок — много опций за свои деньги.','chery6.jpg',0,1200.00,147,1,2),(20,11,'Chery Omoda 5',2023,'1.5 TGDI (147 л.с., 230 Нм) или 1.6 TGDI (186 л.с.) на полном приводе, передний привод или полный (4×4), вариатор CVT25 (1.5) или 7-ступ. робот DCT (1.6). Разгон 0-100 за 9.6 с (1.5) или 7.8 с (1.6). Подвеска: McPherson спереди, многорычажка сзади (на 4×4) или полузависимая балка (на переднем). 10.25\" приборка + 10.25\" медиасистема (объединены в один блок), ассистент движения в пробках, круговой обзор 360°, электрический доводчик дверей.','chery5.jpg',0,1300.00,147,1,2),(21,7,'Seitos',2025,'Компактный кроссовер на новой платформе K3. Двигатели на выбор: 2.0 MPI атмосферный (147 л.с., 179 Нм) в паре с вариатором IVT; либо 1.6 T-GDI турбо (180-195 л.с., 265 Нм) с 8-ступенчатым автоматом (в Корее — 193 л.с., в Европе — 180 л.с.). Также доступна гибридная версия HEV: 1.6 GDI + электромотор, суммарная мощность 178 л.с., 6-ступенчатый робот, e-AWD с дополнительным электромотором на задней оси, функция V2L (питание внешних приборов). Привод — передний или полный (AWD с многорычажной задней подвеской). Габариты выросли: длина 4430 мм, колёсная база 2690 мм, багажник 536 литров. Салон: три экрана — 12.3\" виртуальная приборка, 12.3\" тачскрин мультимедиа и 5\" дисплей климата. Опции: панорамная крыша, проекционный дисплей, аудиосистема Harman Kardon (или Bose), атмосферная подсветка 64 цвета, беспроводная зарядка, камеры кругового обзора. Безопасность: адаптивный круиз с Stop&Go, автоторможение, удержание в полосе, контроль слепых зон. В базе — 9 подушек безопасности (для Кореи). Выдвижные дверные ручки, вертикальные фары и сплошная световая полоса сзади.','kiaSeitos.jpg',0,1800.00,147,2,1); /*!40000 ALTER TABLE `cars` ENABLE KEYS */; UNLOCK TABLES;  -- -- Table structure for table `categories` --  DROP TABLE IF EXISTS `categories`; /*!40101 SET @saved_cs_client     = @@character_set_client */; /*!50503 SET character_set_client = utf8mb4 */; CREATE TABLE `categories` (   `id_category` int NOT NULL AUTO_INCREMENT,   `name_category` varchar(45) NOT NULL,   PRIMARY KEY (`id_category`) ) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci; /*!40101 SET character_set_client = @saved_cs_client */;  -- -- Dumping data for table `categories` --  LOCK TABLES `categories` WRITE; /*!40000 ALTER TABLE `categories` DISABLE KEYS */; INSERT INTO `categories` VALUES (1,'Toyota'),(2,'BMW'),(3,'Mercedes'),(4,'Honda'),(5,'Volkswagen'),(6,'Lada'),(7,'Kia'),(8,'Audi'),(9,'Lexus'),(10,'Tesla'),(11,'Chery'); /*!40000 ALTER TABLE `categories` ENABLE KEYS */; UNLOCK TABLES;  -- -- Table structure for table `chat_senders` --  DROP TABLE IF EXISTS `chat_senders`; /*!40101 SET @saved_cs_client     = @@character_set_client */; /*!50503 SET character_set_client = utf8mb4 */; CREATE TABLE `chat_senders` (   `id_sender` int NOT NULL AUTO_INCREMENT,   `sender_name` varchar(45) NOT NULL,   PRIMARY KEY (`id_sender`) ) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci; /*!40101 SET character_set_client = @saved_cs_client */;  -- -- Dumping data for table `chat_senders` --  LOCK TABLES `chat_senders` WRITE; /*!40000 ALTER TABLE `chat_senders` DISABLE KEYS */; INSERT INTO `chat_senders` VALUES (1,'User'),(2,'Bot'); /*!40000 ALTER TABLE `chat_senders` ENABLE KEYS */; UNLOCK TABLES;  -- -- Table structure for table `favorites` --  DROP TABLE IF EXISTS `favorites`; /*!40101 SET @saved_cs_client     = @@character_set_client */; /*!50503 SET character_set_client = utf8mb4 */; CREATE TABLE `favorites` (   `id_favorit